SELECT

FROM ws_mcp_server_def
WHERE deleted = false
AND (type = 'inner' OR (type = 'private' AND tenant_id = #{tenantId,jdbcType=VARCHAR}))


        AND name_en LIKE CONCAT('%', #{name,jdbcType=VARCHAR}, '%')


        AND name LIKE CONCAT('%', #{name,jdbcType=VARCHAR}, '%')



    and org_type = #{orgType}


    and category = #{category}

ORDER BY created_date DESC,id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) AS total FROM ws_mcp_server_def WHERE deleted = false AND (type = 'inner' OR (type = 'private' AND tenant_id = #{tenantId,jdbcType=VARCHAR}))
AND (name_en LIKE CONCAT('%', #{name,jdbcType=VARCHAR}, '%') OR description_en LIKE CONCAT('%', #{name,jdbcType=VARCHAR}, '%'))
AND (name LIKE CONCAT('%', #{name,jdbcType=VARCHAR}, '%') OR description LIKE CONCAT('%', #{name,jdbcType=VARCHAR}, '%'))
and org_type = #{orgType}
and category = #{category}

